// ThroughputBucket defines model for ThroughputBucket.
type ThroughputBucket struct {
	// At The start of the hour, in UTC.
	At time.Time `json:"at"`

	// ByAgent The same hour split by who ran. Travels with the phase split rather
	// than in its own request: every screen that wants one wants the
	// other, and two queries over the same rows can disagree if a run
	// finishes between them.
	ByAgent map[string]int64 `json:"byAgent"`

	// ByPhase Runs per phase within the hour. A phase with none is absent.
	ByPhase map[string]int64 `json:"byPhase"`

	// Micros What the hour cost, read off the same rows as the count.
	Micros int64 `json:"micros"`
	Total  int64 `json:"total"`
}

// Tool defines model for Tool.
type Tool struct {
	Description *string `json:"description,omitempty"`

	// Effect What a tool does to the world. The domain's `unknown` is deliberately absent: it is the zero value that makes an unclassified tool fail closed, never something a caller may assert.
	Effect Effect `json:"effect"`
	Server string `json:"server"`

	// ToolId Namespaced by server, because two servers naming a tool "search" must not collide into one capability.
	ToolId    string `json:"toolId"`
	Untrusted bool   `json:"untrusted"`
}

// Transport How a tool server is reached. `stdio` is a process this installation runs; `http` is an address it calls. The difference is not cosmetic — a command with arguments is code executed inside the worker's container, which is a far larger thing to hand somebody than a URL.
type Transport string

